export function resolveCloudinaryUrl(imgPathOrSlug?: string, slugHint?: string): string | null {
  if (!imgPathOrSlug && !slugHint) return null;

  const key1 = (imgPathOrSlug || "").trim();
  const key2 = (slugHint || "").trim();

  if (key1.startsWith("http://") || key1.startsWith("https://") || key1.startsWith("data:")) {
    return key1;
  }

  const filename = key1.split("/").pop() || "";
  const baseName = filename.replace(/\.(jpg|jpeg|png|svg|webp)$/i, "");

  const lookupCandidates = [
    filename,
    filename.toLowerCase(),
    baseName,
    baseName.toLowerCase(),
    baseName.toLowerCase().replace(/[-_\s]/g, ""),
    key2,
    key2.toLowerCase(),
    key2.toLowerCase().replace(/[-_\s]/g, "")
  ];

  for (const candidate of lookupCandidates) {
    if (candidate && CLOUDINARY_ASSETS_MAP[candidate]) {
      return CLOUDINARY_ASSETS_MAP[candidate];
    }
  }

  return null;
}
